struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float star(float2 uv, float2 center, float brightness)
{
    float d = length(uv - center);
    return brightness / (d * d * 800.0 + 1.0);
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float3 col = float3(0.0, 0.0, 0.02);
    for (int layer = 0; layer < 4; layer++) {
        float speed = 0.2 + layer * 0.15;
        float scale = 8.0 + layer * 4.0;
        float2 uv = i.uv * scale;
        uv.y += t * speed;
        float2 gv = frac(uv) - 0.5;
        float2 id = floor(uv);
        for (int y = -1; y <= 1; y++) {
            for (int x = -1; x <= 1; x++) {
                float2 offs = float2(x, y);
                float2 cid = id + offs;
                float h = hash21(cid);
                float2 spos = offs - 0.5 + float2(h, frac(h * 34.56)) * 0.8;
                float brightness = 0.3 + 0.7 * frac(h * 12.34);
                float twinkle = 0.7 + 0.3 * sin(t * (2.0 + h * 4.0) + h * 6.28);
                col += star(gv, spos, brightness * twinkle * (0.2 + layer * 0.1));
            }
        }
    }
    return float4(col, 1.0);
}
